import{_ as t,o,c as i,l as a,t as s,N as n}from"./chunks/framework.Bbd9fWQx.js";const b=JSON.parse('{"title":"git-merge-tree | x-cmd man (git man1) | Perform merge without touching index or working tree","titleTemplate":false,"description":"x-cmd man (git man1 Manual Page) | git-merge-tree - Perform merge without touching index or working tree","frontmatter":{"pageClass":"x-man","head":[["meta",{"name":"og:title","content":"git-merge-tree | x-cmd man (git man1) | Perform merge without touching index or working tree"}],["meta",{"name":"og:description","content":"x-cmd man (git man1 Manual Page) | git-merge-tree - Perform merge without touching index or working tree"}]]},"headers":[],"params":{"isMan":true,"man":"git-merge-tree","category":"git man1","desc":"Perform merge without touching index or working tree"},"relativePath":"git/man1/git-merge-tree.md","filePath":"git/man1/git-merge-tree.md"}'),r={name:"git/man1/git-merge-tree.md"},l={class:"visually-hidden"},h=n(`<h2 id="name" tabindex="-1">NAME <a class="header-anchor" href="#name" aria-label="Permalink to &quot;NAME&quot;">​</a></h2><p>git-merge-tree - Perform merge without touching index or working tree</p><h2 id="synopsis" tabindex="-1">SYNOPSIS <a class="header-anchor" href="#synopsis" aria-label="Permalink to &quot;SYNOPSIS&quot;">​</a></h2><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> merge-tree</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [--write-tree] [</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">options</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">] </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">branch</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">1&gt;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">branch</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">2&gt;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> merge-tree</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [--trivial-merge] </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">base-tree</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">branch</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">1&gt;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">branch</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">2&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">deprecated</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span></code></pre></div><h2 id="description" tabindex="-1">DESCRIPTION <a class="header-anchor" href="#description" aria-label="Permalink to &quot;DESCRIPTION&quot;">​</a></h2><p>This command has a modern <strong>--write-tree</strong> mode and a deprecated <strong>--trivial-merge</strong> mode. With the exception of the DEPRECATED DESCRIPTION section at the end, the rest of this documentation describes modern <strong>--write-tree</strong> mode.</p><p>Performs a merge, but does not make any new commits and does not read from or write to either the working tree or index.</p><p>The performed merge will use the same feature as the &quot;real&quot; <strong>git-merge</strong>(1), including:</p><blockquote><p>·</p><p>three way content merges of individual files</p></blockquote><blockquote><p>·</p><p>rename detection</p></blockquote><blockquote><p>·</p><p>proper directory/file conflict handling</p></blockquote><blockquote><p>·</p><p>recursive ancestor consolidation (i.e. when there is more than one merge base, creating a virtual merge base by merging the merge bases)</p></blockquote><blockquote><p>·</p><p>etc.</p></blockquote><p>After the merge completes, a new toplevel tree object is created. See <strong>OUTPUT</strong> below for details.</p><h2 id="options" tabindex="-1">OPTIONS <a class="header-anchor" href="#options" aria-label="Permalink to &quot;OPTIONS&quot;">​</a></h2><p>-z</p><blockquote><p>Do not quote filenames in the &lt;Conflicted file info&gt; section, and end each filename with a NUL character rather than newline. Also begin the messages section with a NUL character instead of a newline. See the section called &quot;OUTPUT&quot; below for more information.</p></blockquote><p>--name-only</p><blockquote><p>In the Conflicted file info section, instead of writing a list of (mode, oid, stage, path) tuples to output for conflicted files, just provide a list of filenames with conflicts (and do not list filenames multiple times if they have multiple conflicting stages).</p></blockquote><p>--[no-]messages</p><blockquote><p>Write any informational messages such as &quot;Auto-merging &lt;path&gt;&quot; or CONFLICT notices to the end of stdout. If unspecified, the default is to include these messages if there are merge conflicts, and to omit them otherwise.</p></blockquote><p>--allow-unrelated-histories</p><blockquote><p>merge-tree will by default error out if the two branches specified share no common history. This flag can be given to override that check and make the merge proceed anyway.</p></blockquote><p>--merge-base=&lt;commit&gt;</p><blockquote><p>Instead of finding the merge-bases for &lt;branch1&gt; and &lt;branch2&gt;, specify a merge-base for the merge, and specifying multiple bases is currently not supported. This option is incompatible with <strong>--stdin</strong>.</p></blockquote><h2 id="output" tabindex="-1">OUTPUT <a class="header-anchor" href="#output" aria-label="Permalink to &quot;OUTPUT&quot;">​</a></h2><p>For a successful merge, the output from git-merge-tree is simply one line:</p><blockquote><pre><code>&lt;OID of toplevel tree&gt;
</code></pre></blockquote><p>Whereas for a conflicted merge, the output is by default of the form:</p><blockquote><pre><code>&lt;OID of toplevel tree&gt;
&lt;Conflicted file info&gt;
&lt;Informational messages&gt;
</code></pre></blockquote><p>These are discussed individually below.</p><p>However, there is an exception. If <strong>--stdin</strong> is passed, then there is an extra section at the beginning, a NUL character at the end, and then all the sections repeat for each line of input. Thus, if the first merge is conflicted and the second is clean, the output would be of the form:</p><blockquote><pre><code>&lt;Merge status&gt;
&lt;OID of toplevel tree&gt;
&lt;Conflicted file info&gt;
&lt;Informational messages&gt;
NUL
&lt;Merge status&gt;
&lt;OID of toplevel tree&gt;
NUL
</code></pre></blockquote><h3 id="merge-status" tabindex="-1">Merge status <a class="header-anchor" href="#merge-status" aria-label="Permalink to &quot;Merge status&quot;">​</a></h3><p>This is an integer status followed by a NUL character. The integer status is:</p><blockquote><pre><code>   0: merge had conflicts
   1: merge was clean
   &amp;lt;0: something prevented the merge from running (e.g. access to repository
objects denied by filesystem)
</code></pre></blockquote><h3 id="oid-of-toplevel-tree" tabindex="-1">OID of toplevel tree <a class="header-anchor" href="#oid-of-toplevel-tree" aria-label="Permalink to &quot;OID of toplevel tree&quot;">​</a></h3><p>This is a tree object that represents what would be checked out in the working tree at the end of <strong>git merge</strong>. If there were conflicts, then files within this tree may have embedded conflict markers. This section is always followed by a newline (or NUL if <strong>-z</strong> is passed).</p><h3 id="conflicted-file-info" tabindex="-1">Conflicted file info <a class="header-anchor" href="#conflicted-file-info" aria-label="Permalink to &quot;Conflicted file info&quot;">​</a></h3><p>This is a sequence of lines with the format</p><blockquote><pre><code>&lt;mode&gt; &lt;object&gt; &lt;stage&gt; &lt;filename&gt;
</code></pre></blockquote><p>The filename will be quoted as explained for the configuration variable <strong>core.quotePath</strong> (see <strong>git-config</strong>(1)). However, if the <strong>--name-only</strong> option is passed, the mode, object, and stage will be omitted. If <strong>-z</strong> is passed, the &quot;lines&quot; are terminated by a NUL character instead of a newline character.</p><h3 id="informational-messages" tabindex="-1">Informational messages <a class="header-anchor" href="#informational-messages" aria-label="Permalink to &quot;Informational messages&quot;">​</a></h3><p>This section provides informational messages, typically about conflicts. The format of the section varies significantly depending on whether <strong>-z</strong> is passed.</p><p>If <strong>-z</strong> is passed:</p><p>The output format is zero or more conflict informational records, each of the form:</p><blockquote><pre><code>&lt;list-of-paths&gt;&lt;conflict-type&gt;NUL&lt;conflict-message&gt;NUL
</code></pre></blockquote><p>where &lt;list-of-paths&gt; is of the form</p><blockquote><pre><code>&lt;number-of-paths&gt;NUL&lt;path1&gt;NUL&lt;path2&gt;NUL...&lt;pathN&gt;NUL
</code></pre></blockquote><p>and includes paths (or branch names) affected by the conflict or informational message in &lt;conflict-message&gt;. Also, &lt;conflict-type&gt; is a stable string explaining the type of conflict, such as</p><blockquote><p>·</p><p>&quot;Auto-merging&quot;</p></blockquote><blockquote><p>·</p><p>&quot;CONFLICT (rename/delete)&quot;</p></blockquote><blockquote><p>·</p><p>&quot;CONFLICT (submodule lacks merge base)&quot;</p></blockquote><blockquote><p>·</p><p>&quot;CONFLICT (binary)&quot;</p></blockquote><p>and &lt;conflict-message&gt; is a more detailed message about the conflict which often (but not always) embeds the &lt;stable-short-type-description&gt; within it. These strings may change in future Git versions. Some examples:</p><blockquote><p>·</p><p>&quot;Auto-merging &lt;file&gt;&quot;</p></blockquote><blockquote><p>·</p><p>&quot;CONFLICT (rename/delete): &lt;oldfile&gt; renamed...but deleted in...&quot;</p></blockquote><blockquote><p>·</p><p>&quot;Failed to merge submodule &lt;submodule&gt; (no merge base)&quot;</p></blockquote><blockquote><p>·</p><p>&quot;Warning: cannot merge binary files: &lt;filename&gt;&quot;</p></blockquote><p>If <strong>-z</strong> is NOT passed:</p><p>This section starts with a blank line to separate it from the previous sections, and then only contains the &lt;conflict-message&gt; information from the previous section (separated by newlines). These are non-stable strings that should not be parsed by scripts, and are just meant for human consumption. Also, note that while &lt;conflict-message&gt; strings usually do not contain embedded newlines, they sometimes do. (However, the free-form messages will never have an embedded NUL character). So, the entire block of information is meant for human readers as an agglomeration of all conflict messages.</p><h2 id="exit-status" tabindex="-1">EXIT STATUS <a class="header-anchor" href="#exit-status" aria-label="Permalink to &quot;EXIT STATUS&quot;">​</a></h2><p>For a successful, non-conflicted merge, the exit status is 0. When the merge has conflicts, the exit status is 1. If the merge is not able to complete (or start) due to some kind of error, the exit status is something other than 0 or 1 (and the output is unspecified). When --stdin is passed, the return status is 0 for both successful and conflicted merges, and something other than 0 or 1 if it cannot complete all the requested merges.</p><h2 id="usage-notes" tabindex="-1">USAGE NOTES <a class="header-anchor" href="#usage-notes" aria-label="Permalink to &quot;USAGE NOTES&quot;">​</a></h2><p>This command is intended as low-level plumbing, similar to <strong>git-hash-object</strong>(1), <strong>git-mktree</strong>(1), <strong>git-commit-tree</strong>(1), <strong>git-write-tree</strong>(1), <strong>git-update-ref</strong>(1), and <strong>git-mktag</strong>(1). Thus, it can be used as a part of a series of steps such as:</p><blockquote><pre><code>NEWTREE=$(git merge-tree --write-tree $BRANCH1 $BRANCH2)
test $? -eq 0 || die &quot;There were conflicts...&quot;
NEWCOMMIT=$(git commit-tree $NEWTREE -p $BRANCH1 -p $BRANCH2)
git update-ref $BRANCH1 $NEWCOMMIT
</code></pre></blockquote><p>Note that when the exit status is non-zero, <strong>NEWTREE</strong> in this sequence will contain a lot more output than just a tree.</p><p>For conflicts, the output includes the same information that you&#39;d get with <strong>git-merge</strong>(1):</p><blockquote><p>·</p><p>what would be written to the working tree (the OID of toplevel tree)</p></blockquote><blockquote><p>·</p><p>the higher order stages that would be written to the index (the Conflicted file info)</p></blockquote><blockquote><p>·</p><p>any messages that would have been printed to stdout (the Informational messages)</p></blockquote><h2 id="input-format" tabindex="-1">INPUT FORMAT <a class="header-anchor" href="#input-format" aria-label="Permalink to &quot;INPUT FORMAT&quot;">​</a></h2><p><em>git merge-tree --stdin</em> input format is fully text based. Each line has this format:</p><blockquote><pre><code>[&lt;base-commit&gt; -- ]&lt;branch1&gt; &lt;branch2&gt;
</code></pre></blockquote><p>If one line is separated by <strong>--</strong>, the string before the separator is used for specifying a merge-base for the merge and the string after the separator describes the branches to be merged.</p><h2 id="mistakes-to-avoid" tabindex="-1">MISTAKES TO AVOID <a class="header-anchor" href="#mistakes-to-avoid" aria-label="Permalink to &quot;MISTAKES TO AVOID&quot;">​</a></h2><p>Do NOT look through the resulting toplevel tree to try to find which files conflict; parse the Conflicted file info section instead. Not only would parsing an entire tree be horrendously slow in large repositories, there are numerous types of conflicts not representable by conflict markers (modify/delete, mode conflict, binary file changed on both sides, file/directory conflicts, various rename conflict permutations, etc.)</p><p>Do NOT interpret an empty Conflicted file info list as a clean merge; check the exit status. A merge can have conflicts without having individual files conflict (there are a few types of directory rename conflicts that fall into this category, and others might also be added in the future).</p><p>Do NOT attempt to guess or make the user guess the conflict types from the Conflicted file info list. The information there is insufficient to do so. For example: Rename/rename(1to2) conflicts (both sides renamed the same file differently) will result in three different file having higher order stages (but each only has one higher order stage), with no way (short of the Informational messages section) to determine which three files are related. File/directory conflicts also result in a file with exactly one higher order stage. Possibly-involved-in-directory-rename conflicts (when &quot;merge.directoryRenames&quot; is unset or set to &quot;conflicts&quot;) also result in a file with exactly one higher order stage. In all cases, the Informational messages section has the necessary info, though it is not designed to be machine parseable.</p><p>Do NOT assume that each paths from Conflicted file info, and the logical conflicts in the Informational messages have a one-to-one mapping, nor that there is a one-to-many mapping, nor a many-to-one mapping. Many-to-many mappings exist, meaning that each path can have many logical conflict types in a single merge, and each logical conflict type can affect many paths.</p><p>Do NOT assume all filenames listed in the Informational messages section had conflicts. Messages can be included for files that have no conflicts, such as &quot;Auto-merging &lt;file&gt;&quot;.</p><p>AVOID taking the OIDS from the Conflicted file info and re-merging them to present the conflicts to the user. This will lose information. Instead, look up the version of the file found within the OID of toplevel tree and show that instead. In particular, the latter will have conflict markers annotated with the original branch/commit being merged and, if renames were involved, the original filename. While you could include the original branch/commit in the conflict marker annotations when re-merging, the original filename is not available from the Conflicted file info and thus you would be losing information that might help the user resolve the conflict.</p><h2 id="deprecated-description" tabindex="-1">DEPRECATED DESCRIPTION <a class="header-anchor" href="#deprecated-description" aria-label="Permalink to &quot;DEPRECATED DESCRIPTION&quot;">​</a></h2><p>Per the DESCRIPTION and unlike the rest of this documentation, this section describes the deprecated <strong>--trivial-merge</strong> mode.</p><p>Other than the optional <strong>--trivial-merge</strong>, this mode accepts no options.</p><p>This mode reads three tree-ish, and outputs trivial merge results and conflicting stages to the standard output in a semi-diff format. Since this was designed for higher level scripts to consume and merge the results back into the index, it omits entries that match &lt;branch1&gt;. The result of this second form is similar to what three-way <em>git read-tree -m</em> does, but instead of storing the results in the index, the command outputs the entries to the standard output.</p><p>This form not only has limited applicability (a trivial merge cannot handle content merges of individual files, rename detection, proper directory/file conflict handling, etc.), the output format is also difficult to work with, and it will generally be less performant than the first form even on successful merges (especially if working in large repositories).</p><h2 id="git" tabindex="-1">GIT <a class="header-anchor" href="#git" aria-label="Permalink to &quot;GIT&quot;">​</a></h2><p>Part of the <strong>git</strong>(1) suite</p>`,89);function c(e,p,d,g,m,f){return o(),i("div",null,[a("h1",l,s(e.$params.man),1),h])}const k=t(r,[["render",c]]);export{b as __pageData,k as default};
